// Protocol indicates the transport protocol.
type Protocol int

// Predefined transport protocols.
const (
	PurePayload Protocol = 0
	Framed      Protocol = 2 // Default fallback for legacy compatibility

	TTHeader Protocol = 1 << iota // Starts at 1 (bit 0)
	_                             // Skip bit 1 (reserved for Framed)
	HTTP
	GRPC
	HESSIAN2

	// Dedicated power-of-2 flags for streaming protocols
	TTHeaderStreaming Protocol = 64  // Dedicated flag for TTHeader streaming
	GRPCStreaming     Protocol = 128 // Dedicated flag for gRPC streaming

	// Composite flags
	TTHeaderFramed = TTHeader | Framed // 1 | 2 = 3
)

// Unknown indicates the protocol is unknown.
const Unknown = "Unknown"

