// String prints human readable information.
// For composite values, returns pipe-separated names of all set flags
// in ascending order of their numeric bit values.
// Example: (GRPC | Framed).String() returns "Framed|GRPC"
func (tp Protocol) String() string {
	if tp == PurePayload {
		return "PurePayload"
	}

	// Define all individual flags in ascending order of their numeric values
	// Order matters: we iterate in bit value order to ensure consistent output
	flags := []struct {
		value Protocol
		name  string
	}{
		{TTHeader, "TTHeader"},           // 1
		{Framed, "Framed"},               // 2
		{HTTP, "HTTP"},                   // 4
		{GRPC, "GRPC"},                   // 8
		{HESSIAN2, "Hessian2"},           // 16
		{TTHeaderStreaming, "TTHeaderStreaming"}, // 64
		{GRPCStreaming, "GRPCStreaming"}, // 128
	}

	var parts []string
	for _, flag := range flags {
		if tp&flag.value != 0 {
			parts = append(parts, flag.name)
		}
	}

	if len(parts) == 0 {
		return Unknown
	}

	// Join with pipe separator
	result := parts[0]
	for i := 1; i < len(parts); i++ {
		result += "|" + parts[i]
	}
	return result
}

